DROP POLICY membership_read ON public.school_memberships;
CREATE POLICY membership_read ON public.school_memberships FOR SELECT TO authenticated USING(user_id=auth.uid() OR private.has_role(auth.uid(),'super_admin') OR (private.is_admin(auth.uid()) AND private.shares_active_school(user_id)));
CREATE FUNCTION private.generated_school_number(_kind text,_school uuid) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cfg public.numbering_settings%ROWTYPE; fmt text; yd int; sd int; start_value bigint; mode text; yp text; val bigint; max_value bigint; candidate text; attempts int:=0; taken boolean; BEGIN SELECT * INTO cfg FROM public.numbering_settings WHERE school_id=_school; IF cfg.id IS NULL THEN RETURN NULL; END IF; IF _kind='admission' THEN fmt:=cfg.admission_format; yd:=cfg.admission_year_digits; sd:=cfg.admission_sequence_digits; start_value:=cfg.admission_sequence_start; mode:='compact'; ELSE fmt:=cfg.employee_format; yd:=cfg.employee_year_digits; sd:=cfg.employee_sequence_digits; start_value:=cfg.employee_sequence_start; mode:=cfg.employee_allocation_mode; END IF; yp:=CASE WHEN yd=0 THEN '' ELSE right(to_char(now(),'YYYY'),yd) END; max_value:=power(10,sd)::bigint-1; IF mode='random' THEN WHILE attempts<300 LOOP attempts:=attempts+1; val:=start_value+floor(random()*GREATEST(max_value-start_value+1,1))::bigint; candidate:=replace(replace(replace(fmt,'{SCHOOL}',cfg.school_code),'{YY}',yp),'{SEQ}',lpad(val::text,sd,'0')); SELECT EXISTS(SELECT 1 FROM public.profiles WHERE employee_id=candidate OR admission_number=candidate) OR EXISTS(SELECT 1 FROM public.admissions WHERE admission_number=candidate) INTO taken; IF NOT taken THEN RETURN candidate; END IF; END LOOP; END IF; INSERT INTO public.numbering_counters(school_id,kind,year_key,last_value) VALUES(cfg.school_id,_kind,yp,start_value) ON CONFLICT(school_id,kind,year_key) DO UPDATE SET last_value=GREATEST(public.numbering_counters.last_value+1,start_value),updated_at=now() RETURNING last_value INTO val; IF val>max_value THEN RAISE EXCEPTION 'School numbering sequence exhausted'; END IF; RETURN replace(replace(replace(fmt,'{SCHOOL}',cfg.school_code),'{YY}',yp),'{SEQ}',lpad(val::text,sd,'0')); END $$;
REVOKE ALL ON FUNCTION private.generated_school_number(text,uuid) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.next_generated_number(_kind text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid; BEGIN sid:=private.active_school_id(); IF sid IS NULL THEN RETURN NULL; END IF; RETURN private.generated_school_number(_kind,sid); END $$;
CREATE OR REPLACE FUNCTION public.assign_admission_row_number() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE generated text; BEGIN IF NEW.admission_number IS NULL OR NEW.admission_number='' THEN generated:=private.generated_school_number('admission',NEW.school_id); NEW.admission_number:=COALESCE(generated,'ADM-'||to_char(now(),'YYYY')||'-'||lpad(nextval('public.admission_number_seq')::text,4,'0')); END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.assign_admission_row_number() FROM PUBLIC,anon,authenticated;